import csv
import io


def rows(text):
    """Yield one list of fields per data row (standard CSV rules), header skipped."""
    reader = csv.reader(
        io.StringIO(text), delimiter=',', quotechar='"', doublequote=True
    )
    first = True
    for record in reader:
        if first:
            first = False
            continue
        yield record

